<template>
  <q-page padding>
    <div class="row items-center justify-between q-mb-lg"><div><div class="text-h4 page-title">Inventario</div><div class="page-subtitle">Control de existencias, entradas, salidas y trazabilidad.</div></div><q-btn outline color="cyan-4" icon="refresh" label="Actualizar" :loading="loading" @click="load"/></div>
    <div class="row q-col-gutter-md q-mb-lg"><div class="col-12 col-sm-3"><q-card flat class="metric-card q-pa-md"><div class="metric-label">Stock físico</div><div class="metric-value">{{ totalUnits }}</div></q-card></div><div class="col-12 col-sm-3"><q-card flat class="metric-card q-pa-md"><div class="metric-label">Reservado online</div><div class="metric-value text-cyan-3">{{ reservedUnits }}</div></q-card></div><div class="col-12 col-sm-3"><q-card flat class="metric-card q-pa-md"><div class="metric-label">Productos críticos</div><div class="metric-value text-red-3">{{ lowCount }}</div><div class="text-caption text-muted">5 unidades o menos</div></q-card></div><div class="col-12 col-sm-3"><q-card flat class="metric-card q-pa-md"><div class="metric-label">Valor de inventario</div><div class="metric-value">Bs {{ money(stockValue) }}</div></q-card></div></div>
    <q-card flat class="panel"><q-card-section class="row q-col-gutter-sm"><div class="col-12 col-md-8"><q-input v-model="search" outlined dense dark clearable label="Buscar producto"><template #prepend><q-icon name="search"/></template></q-input></div><div class="col-12 col-md-4"><q-select v-model="filter" :options="['Todos','Stock bajo','Sin stock']" outlined dense dark label="Filtro"/></div></q-card-section>
      <q-table :rows="filtered" :columns="columns" row-key="id" dark flat class="table-dark" :loading="loading"><template #body-cell-Stock="p"><q-td :props="p"><q-chip dense :color="Number(p.row.Stock)===0?'red-10':Number(p.row.Stock)<=5?'orange-10':'green-10'" text-color="white">{{p.row.Stock}} u.</q-chip></q-td></template><template #body-cell-reservado="p"><q-td :props="p"><q-chip dense color="blue-10" text-color="cyan-2">{{p.row.Stock_reservado || 0}} u.</q-chip></q-td></template><template #body-cell-disponible="p"><q-td :props="p"><q-chip dense :color="Number(p.row.Disponible ?? p.row.Stock)<=5?'orange-10':'green-10'" text-color="white">{{p.row.Disponible ?? p.row.Stock}} u.</q-chip></q-td></template><template #body-cell-Precio="p"><q-td :props="p">Bs {{money(p.row.Precio)}}</q-td></template><template #body-cell-acciones="p"><q-td :props="p"><q-btn flat round dense color="green-4" icon="add" @click="openMove(p.row,'entrada')"><q-tooltip>Entrada</q-tooltip></q-btn><q-btn flat round dense color="red-4" icon="remove" @click="openMove(p.row,'salida')"><q-tooltip>Salida</q-tooltip></q-btn><q-btn flat round dense color="cyan-4" icon="history" @click="history(p.row)"><q-tooltip>Historial</q-tooltip></q-btn></q-td></template></q-table>
    </q-card>
    <q-dialog v-model="moveDialog"><q-card class="panel text-white" style="width:460px;max-width:92vw"><q-card-section><div class="text-h6">{{move.tipo==='entrada'?'Registrar entrada':'Registrar salida'}}</div><div class="text-caption text-muted">{{selected?.Nombre}} · Stock actual {{selected?.Stock}}</div></q-card-section><q-card-section><q-input v-model.number="move.cantidad" type="number" min="1" outlined dark label="Cantidad" class="q-mb-md"/><q-select v-model="move.motivo" :options="reasons" outlined dark label="Motivo"/></q-card-section><q-card-actions align="right"><q-btn flat label="Cancelar" v-close-popup/><q-btn :color="move.tipo==='entrada'?'green':'red'" :label="move.tipo==='entrada'?'Registrar entrada':'Registrar salida'" :loading="saving" @click="saveMove"/></q-card-actions></q-card></q-dialog>
    <q-dialog v-model="historyDialog"><q-card class="panel text-white" style="width:900px;max-width:96vw"><q-card-section class="row items-center justify-between"><div><div class="text-h6">Movimientos de stock</div><div class="text-caption text-muted">{{selected?.Nombre}}</div></div><q-btn flat round icon="close" v-close-popup/></q-card-section><q-table :rows="movements" :columns="movementColumns" row-key="id" dark flat class="table-dark" :loading="historyLoading"><template #body-cell-tipo="p"><q-td :props="p"><q-chip dense :color="p.row.tipo==='entrada'?'green-10':'red-10'" text-color="white">{{p.row.tipo}}</q-chip></q-td></template></q-table></q-card></q-dialog>
  </q-page>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue';import {useQuasar} from 'quasar';import api from '../services/api';const $q=useQuasar();const products=ref([]),movements=ref([]),loading=ref(false),saving=ref(false),historyLoading=ref(false),moveDialog=ref(false),historyDialog=ref(false),selected=ref(null),search=ref(''),filter=ref('Todos');const move=ref({tipo:'entrada',cantidad:1,motivo:''});const reasons=['Ajuste de inventario','Devolución','Producto dañado','Corrección de conteo','Otro'];const columns=[{name:'id',label:'#',field:'id',align:'left'},{name:'Nombre',label:'Producto',field:'Nombre',align:'left'},{name:'Precio',label:'Precio',field:'Precio',align:'right'},{name:'Stock',label:'Físico',field:'Stock',align:'center'},{name:'reservado',label:'Reservado',field:'Stock_reservado',align:'center'},{name:'disponible',label:'Disponible',field:'Disponible',align:'center'},{name:'acciones',label:'Acciones',field:'acciones',align:'center'}];const movementColumns=[{name:'created_at',label:'Fecha',field:'created_at',align:'left'},{name:'tipo',label:'Tipo',field:'tipo',align:'center'},{name:'cantidad',label:'Cantidad',field:'cantidad',align:'center'},{name:'stock_anterior',label:'Antes',field:'stock_anterior',align:'center'},{name:'stock_nuevo',label:'Después',field:'stock_nuevo',align:'center'},{name:'motivo',label:'Motivo',field:'motivo',align:'left'}];const money=v=>Number(v||0).toFixed(2);const totalUnits=computed(()=>products.value.reduce((s,p)=>s+Number(p.Stock||0),0));const reservedUnits=computed(()=>products.value.reduce((s,p)=>s+Number(p.Stock_reservado||0),0));const lowCount=computed(()=>products.value.filter(p=>Number(p.Disponible ?? p.Stock)<=5).length);const stockValue=computed(()=>products.value.reduce((s,p)=>s+Number(p.Stock||0)*Number(p.Precio||0),0));const filtered=computed(()=>products.value.filter(p=>{const q=search.value.toLowerCase().trim();const match=!q||(p.Nombre||'').toLowerCase().includes(q);const n=Number(p.Disponible ?? p.Stock ?? 0);const f=filter.value==='Todos'||(filter.value==='Stock bajo'&&n<=5)||(filter.value==='Sin stock'&&n===0);return match&&f}));const load=async()=>{loading.value=true;try{const r=await api.get('/productos');products.value=r.data.productos||[]}catch(e){$q.notify({type:'negative',message:e.userMessage||'No se pudo cargar inventario'})}finally{loading.value=false}};const openMove=(p,t)=>{selected.value=p;move.value={tipo:t,cantidad:1,motivo:'Ajuste de inventario'};moveDialog.value=true};const saveMove=async()=>{if(Number(move.value.cantidad)<1)return;if(move.value.tipo==='salida'&&Number(move.value.cantidad)>Number(selected.value.Disponible ?? selected.value.Stock))return $q.notify({type:'warning',message:`La salida supera el stock disponible (${selected.value.Disponible ?? selected.value.Stock}).`});saving.value=true;try{await api.post('/movimientos-stock',{id_producto:selected.value.id,...move.value});moveDialog.value=false;$q.notify({type:'positive',message:'Movimiento registrado.'});await load()}catch(e){$q.notify({type:'negative',message:e.userMessage||'No se pudo registrar el movimiento'})}finally{saving.value=false}};const history=async p=>{selected.value=p;historyDialog.value=true;historyLoading.value=true;try{const r=await api.get(`/productos/${p.id}/movimientos-stock`);movements.value=r.data.movimientos||[]}finally{historyLoading.value=false}};onMounted(load)
</script>
